/**
 * Conversational sign lexicon (pose-based, no SiGML/CWASA).
 *
 * Data: web/public/lexicon/lexicon.json, generated by scripts/gen-lexicon.mjs
 * from the procedural motion generator (motionGen.mjs). Each word is 5
 * keyframes of 225-dim Holistic landmarks; letters are 5 keyframes each.
 * Frames are interpolated at runtime (smoothstep) to a fluid sequence.
 *
 * The SAME frame stream drives both Pipeline B renderers:
 *   - SkeletonView (2D canvas skeleton), and
 *   - Avatar (Three.js, retargeted from pose landmarks).
 *
 * Out-of-lexicon words are finger-spelled letter by letter.
 */
import { FEATURE_DIM, FRAMES } from './holistic'
import {
  buildFrame,
  generateLetterKeyframes,
  generateWordKeyframes,
  SHAPES,
} from './motionGen.mjs'

export interface LexiconData {
  version: number
  generatedFrom: string
  words: Record<string, number[][]>
  letters: Record<string, number[][]>
}

export interface Lexicon {
  data: LexiconData
  hasWord: (token: string) => boolean
  /** Frames (225-dim each) to sign one token; fingerspells unknown words. */
  framesForToken: (token: string) => Float32Array[]
  /** Frames for a whole gloss list, with per-token frame counts. */
  framesForTokens: (tokens: string[]) => { frames: Float32Array[]; boundaries: number[] }
}

let lexiconPromise: Promise<Lexicon> | null = null

function smoothstep(t: number): number {
  return t * t * (3 - 2 * t)
}

/** Interpolate keyframes into `outFrames` evenly spaced frames. */
export function expandKeyframes(
  keyframes: number[][],
  outFrames = 24,
): Float32Array[] {
  if (keyframes.length === 0) return []
  if (keyframes.length === 1) {
    return Array.from({ length: outFrames }, () => Float32Array.from(keyframes[0]))
  }
  const out: Float32Array[] = []
  const legs = keyframes.length - 1
  for (let f = 0; f < outFrames; f++) {
    const t = outFrames === 1 ? 0 : f / (outFrames - 1)
    const scaled = Math.min(t, 0.999999) * legs
    const leg = Math.floor(scaled)
    const lt = smoothstep(scaled - leg)
    const a = keyframes[leg]
    const b = keyframes[leg + 1]
    const frame = new Float32Array(FEATURE_DIM)
    for (let i = 0; i < FEATURE_DIM; i++) {
      frame[i] = a[i] + (b[i] - a[i]) * lt
    }
    out.push(frame)
  }
  return out
}

const LETTER_FRAMES = 10

function letterFrames(letter: string, data: LexiconData): Float32Array[] {
  const kf = data.letters[letter] ?? generateLetterKeyframes(letter)
  return expandKeyframes(kf, LETTER_FRAMES)
}

export function loadLexicon(): Promise<Lexicon> {
  if (!lexiconPromise) {
    lexiconPromise = (async (): Promise<Lexicon> => {
      let data: LexiconData | null = null
      try {
        const r = await fetch(`${import.meta.env.BASE_URL}lexicon/lexicon.json`)
        if (r.ok) data = (await r.json()) as LexiconData
      } catch {
        data = null
      }
      if (!data) {
        // Fall back to generating keyframes in-memory from motionGen.
        const words: Record<string, number[][]> = {}
        const { VOCAB_WORDS } = await import('./motionGen.mjs')
        for (const w of VOCAB_WORDS) words[w] = generateWordKeyframes(w)
        const letters: Record<string, number[][]> = {}
        for (let c = 65; c <= 90; c++) {
          const letter = String.fromCharCode(c)
          letters[letter] = generateLetterKeyframes(letter)
        }
        data = { version: 0, generatedFrom: 'in-memory motionGen fallback', words, letters }
      }
      const hasWord = (token: string) => token in data!.words
      const framesForToken = (token: string): Float32Array[] => {
        if (hasWord(token)) return expandKeyframes(data!.words[token], 24)
        // Unknown word -> finger-spell it.
        const out: Float32Array[] = []
        for (const ch of token) {
          if (/[A-Z]/.test(ch)) out.push(...letterFrames(ch, data!))
        }
        return out
      }
      const framesForTokens = (tokens: string[]) => {
        const frames: Float32Array[] = []
        const boundaries: number[] = []
        for (const t of tokens) {
          const fs = framesForToken(t)
          boundaries.push(frames.length + fs.length)
          frames.push(...fs)
        }
        return { frames, boundaries }
      }
      return { data, hasWord, framesForToken, framesForTokens }
    })()
  }
  return lexiconPromise
}

/** Rest frame (all landmarks at the generator's rest pose). */
export function restFrame(): Float32Array {
  return buildFrame(
    [0.3, 0.61, -0.05],
    [0.7, 0.61, -0.05],
    SHAPES.FLAT,
    SHAPES.FLAT,
  )
}

export { FRAMES }
